import re

_NUM = r'[0-9]+(?:[.,][0-9]+)?'
_WEEK_RE = re.compile(r'P(' + _NUM + r')W')
_BODY_RE = re.compile(
    r'P(?:(' + _NUM + r')D)?'
    r'(T(?:(' + _NUM + r')H)?(?:(' + _NUM + r')M)?(?:(' + _NUM + r')S)?)?'
)


def _to_float(s):
    return float(s.replace(',', '.'))


def parse_duration(text: str) -> float:
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    m = _WEEK_RE.fullmatch(text)
    if m:
        return float(_to_float(m.group(1)) * 7 * 86400)

    m = _BODY_RE.fullmatch(text)
    if not m:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")

    day, t_part, hours, minutes, seconds = m.group(1), m.group(2), m.group(3), m.group(4), m.group(5)

    parts = [(day, 86400), (hours, 3600), (minutes, 60), (seconds, 1)]
    present = [(v, f) for v, f in parts if v is not None]

    if not present:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    if t_part is not None and hours is None and minutes is None and seconds is None:
        raise ValueError(f"'T' must be followed by a time component: {text!r}")

    for v, _ in present[:-1]:
        if '.' in v or ',' in v:
            raise ValueError(f"only the last component may have a fraction: {text!r}")

    total = 0.0
    for v, factor in present:
        total += _to_float(v) * factor
    return float(total)
